import{_ as l,l as i,o as a,c as s,v as o,p as d,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"重定位类型","description":"","frontmatter":{"title":"重定位类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/relocation-types.md","filePath":"cs/relocation-types.md","lastUpdated":1789023840000}'),_={name:"cs/relocation-types.md"};function h(T,e,E,A,B,m){const r=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="重定位类型" tabindex="-1">重定位类型 <a class="header-anchor" href="#重定位类型" aria-label="Permalink to &quot;重定位类型&quot;">​</a></h1><div class="epigraph"><p>每条重定位记录写明：在这一偏移，用符号的地址按何种公式填多少位。ABS、PC 相对、GOT、TLS 各是一种类型。</p><footer>—— 据 ELF 规范与 psABI（`R_X86_64_*`、`R_RISCV_*`）；主干[链接与重定位](/cs/link-reloc)；Levine 整理</footer></div><p>上一课<a href="/cs/symbol-interposition">符号插入</a> 决定绑到谁。缺口是<strong>怎么写成指令编码</strong>：类型不同，公式 <code>S+A-P</code>、<code>G+A</code> 等不同。主干给过直觉。本课钉类型家族，不枚举全部枚举值。ICF 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>汇编器对 <code>call foo</code> 发一条对 <code>foo</code> 的 PC 相对重定位。链接或加载时计算位移，检查是否溢出立即数。缺口是<strong>类型 → 公式 → 宽度</strong>，不是预加载序。</p><p>动态：<code>R_*_GLOB_DAT</code>、<code>JUMP_SLOT</code> 填 GOT/PLT。TLS：<code>TPOFF</code> 等，模型不同（GD/IE/LE）。</p><h3 id="类型不是「再编译」" tabindex="-1">类型不是「再编译」 <a class="header-anchor" href="#类型不是「再编译」" aria-label="Permalink to &quot;类型不是「再编译」&quot;">​</a></h3><p>链接器按记录改字节，不调前端。溢出则报 <code>relocation truncated</code>。选择器应选得上的指令，否则后端要改用 GOT 间接。</p><p><span class="marginnote">psABI 文档是权威表。本课家族：绝对、相对、GOT、PLT、TLS。不抄一百行枚举。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器：PIC 则多发 GOT 型。链接器：静态应用公式；动态把部分记录拷进 <code>rela.dyn</code> 给加载器。检查：对齐、范围。</p>',11)),(a(),d(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E5%81%8F%E7%A7%BB%20%2B%20%E7%B1%BB%E5%9E%8B%20%2B%20%E7%AC%A6%E5%8F%B7%20%2B%20addend%22%5D%20--%3E%20F%5B%22%E5%85%AC%E5%BC%8F%22%5D%0A%20%20F%20--%3E%20BYTES%5B%22%E5%86%99%E5%85%A5%E7%BC%96%E7%A0%81%22%5D%0A%20%20F%20--%3E%20FAIL%5B%22%E6%BA%A2%E5%87%BA%E5%88%99%E6%8A%A5%E9%94%99%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与<a href="/cs/tree-pattern-isel">指令选择</a>：选 <code>b</code> 还是 <code>auipc+jalr</code> 取决于估计范围与 PIC。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RELA vs REL：加数在记录里还是在被改处。Relaxation：链接器把远跳改近跳，删序列——RISC-V 常见。不要假设所有类型都可 relax。</p><p>安全：写重定位的段权限，TEXTREL 使文本可写，应避免。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 TLS 全部模型推导。后课默认：重定位类型由 psABI 定义。下一课 ICF：相同代码节折叠，依赖重定位可调整。</p><p>也不把重定位当 git rebase。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型编码公式与宽度；失败则截断错误。</li><li>PIC/TLS/PLT 使用不同家族。</li><li>relaxation 是链接期再选择。</li><li>出处：ELF 与 psABI；Levine；对照主干 link-reloc。</li></ul>',9))])}const P=l(_,[["render",h]]);export{f as __pageData,P as default};
